import data from '../data/scale-c.json';
import type { FirmChangelogEntry } from './firmUpdates';

/**
 * Scale C (approved by Geyer on 2026-11-25, SCORING.md "Scale C"): a ceiling
 * earned with evidence (age, payouts at scale), minus points for sourced facts
 * (contract clauses, Trustpilot notice, regulator warnings). Unknown items cost
 * nothing. Applied only to firms whose contract was read by hand; the data is
 * generated by scripts/build-scale-c.py and must not be edited by hand.
 */
export type ScaleCCode =
  | 'B1' | 'B2' | 'B2A' | 'B3' | 'B4' | 'B5' | 'B6' | 'B7'
  | 'CONS' | 'TPW' | 'TPMID' | 'TPR' | 'REGWARN' | 'E_HARSH' | 'A1' | 'A1_OLD_UNCLEAR' | 'A2ISO'
  | 'D_PAYOUT_CAP' | 'D_PAYOUT_CONDITIONS' | 'D_ACCOUNT_ENDS_AFTER_PAYOUTS' | 'D_FUNDED_TRAILING_DRAWDOWN' | 'D_SPLIT_REDUCTION';

export type ScaleCTier = 'unknown' | 'lt1' | 'y1to2' | 'y2plus' | 'y3evidence' | 'y5evidence' | 'y8veryLarge';

export type ScaleCPenalty = { code: ScaleCCode; points: number; text: string; source: string; locator: string };

export type ScaleCEvidence =
  | { kind: 'tracker'; amountUSD: number }
  | { kind: 'trustpilot'; rating: number; count: number }
  | { kind: 'stats' };

export type ScaleCEntry = {
  score: number;
  previous: number;
  raw: number;
  ceiling: number;
  tier: ScaleCTier;
  founded: number | null;
  ceilingEvidence: ScaleCEvidence[];
  penalties: ScaleCPenalty[];
  reading: 'full' | 'excerpts';
  checkedOn: string;
  contractCap?: number;
  priorRevisions?: FirmChangelogEntry[];
  revisionSource?: string;
  revisionReason?: 'rbi-exemption';
  revisionOn?: string;
};

const FIRMS = (data as unknown as { firms: Record<string, ScaleCEntry> }).firms;
export const SCALE_C_APPROVED_ON = (data as { approvedOn: string }).approvedOn;

export function getScaleC(slug: string): ScaleCEntry | undefined {
  return FIRMS[slug];
}

/**
 * Firms whose terms have not been read in full by hand are capped at 60
 * (Geyer, 2026-11-25): an unread contract must never rank above a read one.
 */
export const UNAUDITED_SCORE_CAP = 60;
export function isFullyRead(slug: string): boolean {
  return FIRMS[slug]?.reading === 'full';
}

/** Contract-clause codes (capped together at `contractCap`). */
export const SCALE_C_CONTRACT_CODES: ScaleCCode[] = ['B1', 'B2', 'B2A', 'B3', 'B4', 'B5', 'B6', 'B7'];

/** Dated changelog line shown in the firm's "Update history". */
export function scaleCChangelog(slug: string): FirmChangelogEntry[] {
  const entry = FIRMS[slug];
  if (!entry) return [];
  const prior = entry.priorRevisions ?? [];
  if (entry.previous === entry.score) return prior;
  const lost = entry.penalties.map((item) => `${item.code} −${item.points}`).join(', ') || 'no penalty';
  const source = entry.revisionSource ?? entry.penalties.find((item) => item.source.startsWith('https://'))?.source ?? 'https://www.propradar.tech/audit';
  return [...prior, {
    date: entry.revisionOn ?? entry.checkedOn,
    summary: entry.revisionReason === 'rbi-exemption' ? `Scale C policy update (2026-11-27): ${entry.previous} → ${entry.score}. Reserve Bank of India alert-list warnings are informational and no longer deduct points; other penalties and ceiling unchanged.` : entry.revisionSource ? `Targeted counter-audit under unchanged Scale C: ${entry.previous} → ${entry.score}. Ceiling ${entry.ceiling}; points lost: ${lost}. Previously recorded full-read status retained; newly sourced clauses checked on ${entry.checkedOn}.` : `Score recalculated with scale C (approved 2026-11-25): ${entry.previous} → ${entry.score}. Ceiling ${entry.ceiling}; points lost: ${lost}. ${entry.reading === 'full' ? 'Contract read in full.' : `Flagged clauses re-read by hand; a rise waits for a full reading${entry.score > UNAUDITED_SCORE_CAP ? ` and the displayed score is capped at ${UNAUDITED_SCORE_CAP} until then` : ''}.`}`,
    source,
    fields: ['score'],
  }];
}
